37 | public class QuickPerfSpringRunner extends BlockJUnit4ClassRunner {
38 | 
39 |     // Only used if test method is executed in a dedicated JVM
40 |     private static SpringRunnerWithQuickPerfFeatures QUICK_PERF_SPRING_RUNNER_FOR_SPECIFIC_JVM;
41 | 
42 |     private SpringRunnerWithQuickPerfFeatures springRunnerWithQuickPerfFeatures;
43 | 
44 |     private SpringRunnerWithCallableProtectedMethods springRunner;
45 | 
46 |     private QuickPerfConfigs quickPerfConfigs;
47 | 
48 |     private final Class<?> testClass;
49 | 
50 |     private boolean quickPerfFeaturesAreDisabled;
51 | 
52 |     private static final Statement NO_STATEMENT = new Statement() {
53 |         @Override
54 |         public void evaluate() {}
55 |     };
56 | 
57 |     private TestExecutionContext testExecutionContext;
58 | 
59 |     private boolean testMethodToBeLaunchedInASpecificJvm;
60 | 
61 |     public QuickPerfSpringRunner(Class<?> klass) throws InitializationError {
62 |         super(init(klass));
63 |         if (!SystemProperties.TEST_CODE_EXECUTING_IN_NEW_JVM.evaluate()) {
64 |             quickPerfConfigs = QuickPerfConfigsLoader.INSTANCE.loadQuickPerfConfigs();
65 |         }
66 |         this.testClass = klass;
67 |     }
68 | 
69 |     private static Class<?> init(Class<?> klass) {
70 |         if (SystemProperties.TEST_CODE_EXECUTING_IN_NEW_JVM.evaluate()) {
71 |             QUICK_PERF_SPRING_RUNNER_FOR_SPECIFIC_JVM = SpringRunnerWithQuickPerfFeatures.build(klass);
72 |         }
73 |         return klass;
74 |     }
75 | 
76 |     @Override
77 |     protected Statement methodInvoker(FrameworkMethod frameworkMethod, Object test) {
78 | 
79 |         Method testMethod = frameworkMethod.getMethod();
80 | 
81 |         if(quickPerfFeaturesAreDisabled) {
82 |           return springRunner.methodInvoker(frameworkMethod, test);
83 |         }
84 | 
85 |         if (     testMethodToBeLaunchedInASpecificJvm
86 |              && !SystemProperties.TEST_CODE_EXECUTING_IN_NEW_JVM.evaluate()) {
87 |             testExecutionContext = TestExecutionContext.buildNewJvmFrom(quickPerfConfigs
88 |                                                                       , testMethod
89 |             );
90 |             return NO_STATEMENT;
91 |         }
92 | 
93 |         int runnerAllocationOffset = 0;
94 |         testExecutionContext = TestExecutionContext.buildFrom(quickPerfConfigs
95 |                                                             , testMethod
96 |                                                             , runnerAllocationOffset);
97 | 
98 |         if(SystemProperties.TEST_CODE_EXECUTING_IN_NEW_JVM.evaluate()) {
99 |             return QUICK_PERF_SPRING_RUNNER_FOR_SPECIFIC_JVM.methodInvoker(frameworkMethod, test);
100 |         }
101 | 
102 |         return springRunnerWithQuickPerfFeatures.methodInvoker(frameworkMethod, test);
103 | 
104 |     }
105 | 
106 |     @Override
107 |     protected Statement withBefores(FrameworkMethod frameworkMethod, Object testInstance, Statement statement) {
108 |         if(quickPerfFeaturesAreDisabled) {
109 |             return springRunner.withBefores(frameworkMethod, testInstance, statement);
110 |         }
111 |         if (        testMethodToBeLaunchedInASpecificJvm
112 |                 && !SystemProperties.TEST_CODE_EXECUTING_IN_NEW_JVM.evaluate()) {
113 |             return NO_STATEMENT;
114 |         }
115 |         if(SystemProperties.TEST_CODE_EXECUTING_IN_NEW_JVM.evaluate()) {
116 |             return QUICK_PERF_SPRING_RUNNER_FOR_SPECIFIC_JVM.withBefores(frameworkMethod, testInstance, statement);
117 |         }
118 |         return springRunnerWithQuickPerfFeatures.withBefores(frameworkMethod, testInstance, statement);
119 |     }
120 | 
121 |     @Override
122 |     protected Statement withAfters(FrameworkMethod frameworkMethod, Object testInstance, Statement statement) {
123 |         if(quickPerfFeaturesAreDisabled) {
124 |             return springRunner.withAfters(frameworkMethod, testInstance, statement);
125 |         }
126 |         if (SystemProperties.TEST_CODE_EXECUTING_IN_NEW_JVM.evaluate()) {
127 |             return QUICK_PERF_SPRING_RUNNER_FOR_SPECIFIC_JVM.withAfters(frameworkMethod, testInstance, statement);
128 |         }
129 |         if(testMethodToBeLaunchedInASpecificJvm) {
130 |             return new MainJvmAfterJUnitStatement(frameworkMethod
131 |                                                 , testExecutionContext
132 |                                                 , quickPerfConfigs
133 |                                                 , NO_STATEMENT);
134 |         }
135 |         // The test method is not executed in a specific JVM and performance-related properties
136 |         // are evaluated
137 |         return springRunnerWithQuickPerfFeatures.withAfters(frameworkMethod, testInstance, statement);
138 |     }
