189 |             return QUICK_PERF_SPRING_RUNNER_FOR_SPECIFIC_JVM.createTest();
190 |         }
191 |         if(quickPerfFeaturesAreDisabled) {
192 |             return springRunner.createTest();
193 |         }
194 |         return super.createTest();
195 |     }
