197 |     @Override
198 |     protected void runChild(FrameworkMethod frameworkMethod, RunNotifier notifier) {
199 | 
200 |         Annotation[] annotations = retrieveAnnotations(frameworkMethod);
201 | 
202 |         if (SystemProperties.TEST_CODE_EXECUTING_IN_NEW_JVM.evaluate()) {
203 |             QUICK_PERF_SPRING_RUNNER_FOR_SPECIFIC_JVM.runChild(frameworkMethod, notifier);
204 |         } else if(quickPerfFeaturesAreDisabled(annotations)) {
205 |             this.quickPerfFeaturesAreDisabled = true;
206 |             this.springRunner = SpringRunnerWithCallableProtectedMethods
207 |                                .buildSpringRunner(testClass);
208 |             springRunner.runChild(frameworkMethod, notifier);
209 |         } else {
210 |             SetOfAnnotationConfigs testAnnotationConfigs = this.quickPerfConfigs.getTestAnnotationConfigs();
211 |             this.testMethodToBeLaunchedInASpecificJvm = testAnnotationConfigs.hasTestMethodToBeLaunchedInASpecificJvmWith(annotations);
212 | 
213 |             if (testMethodToBeLaunchedInASpecificJvm) {
214 |                 super.runChild(frameworkMethod, notifier);
215 |             } else {
216 |                 Method method = frameworkMethod.getMethod();
217 |                 Class<?> testClass = method.getDeclaringClass();
218 |                 this.springRunnerWithQuickPerfFeatures =
219 |                     SpringRunnerWithQuickPerfFeatures.build(testClass);
220 |                 springRunnerWithQuickPerfFeatures.runChild(frameworkMethod, notifier);
221 |             }
222 | 
223 |         }
224 |     }
