226 |     private Annotation[] retrieveAnnotations(FrameworkMethod frameworkMethod) {
227 | 
228 |         QuickPerfConfigs quickPerfConfigs = QuickPerfConfigsLoader.INSTANCE.loadQuickPerfConfigs();
229 |         SetOfAnnotationConfigs setOfAnnotationConfigs = quickPerfConfigs.getTestAnnotationConfigs();
230 | 
231 |         Method method = frameworkMethod.getMethod();
232 | 
233 |         AnnotationsExtractor annotationsExtractor = AnnotationsExtractor.INSTANCE;
234 |         return annotationsExtractor.extractAnnotationsFor(method, setOfAnnotationConfigs);
